{"path":"assets/css/styles.css","content":"/* Glass morph aesthetic and layout */
:root{
  --bg:#0f1724;
  --glass-bg: rgba(255,255,255,0.06);
  --glass-border: rgba(255,255,255,0.08);
  --accent:#7bd389;
  --muted:#b9c2cf;
  --card:#0b1220;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#eaf0f6;background:linear-gradient(180deg,var(--bg),#071020);}
.wrap{max-width:1100px;margin:0 auto;padding:28px}
.site-header{backdrop-filter:blur(6px);background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border-bottom:1px solid var(--glass-border);position:sticky;top:0;z-index:10}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.logo{font-weight:700;color:var(--accent);text-decoration:none}
.nav a{margin:0 8px;color:var(--muted);text-decoration:none;font-size:0.95rem}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;background:rgba(255,255,255,0.03);color:var(--muted);border:1px solid transparent;text-decoration:none}
.btn.primary{background:linear-gradient(135deg,#5fd18e,#3bb27a);color:#042018;border:0}
.primary-cta{background:transparent;border:1px solid var(--glass-border);padding:8px 10px}
.hero{display:flex;align-items:stretch;padding:48px 0}
.hero-inner{display:flex;gap:28px}
.hero-copy{flex:1}
.hero-pattern img{width:320px;opacity:0.9}
.lead{color:var(--muted);margin-top:6px}
.mood-module{margin-top:18px;background:var(--glass-bg);padding:14px;border-radius:12px;border:1px solid var(--glass-border);width:100%;max-width:520px}
.mood-module label{display:block;color:var(--muted);margin-bottom:6px}
.mood-module select{width:100%;padding:10px;border-radius:8px;background:transparent;border:1px solid var(--glass-border);color:#fff}
.method-card{margin-top:12px;padding:12px;border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border:1px solid rgba(255,255,255,0.03)}
.method-card h3{margin:0 0 6px 0}
.mini-timeline{margin-top:18px;color:var(--muted)}
.mini-timeline .phase{padding:8px 0}
.disclaimer{font-size:0.82rem;color:#9aa6b3}
.social-proof blockquote{background:var(--card);padding:12px;border-radius:10px;border:1px solid var(--glass-border);color:var(--muted);margin:12px 0}
.benefits ul{list-style:none;padding:0}
.benefits li{padding:10px 0;border-bottom:1px dashed rgba(255,255,255,0.02);color:var(--muted)}
.process .timeline{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px;margin-top:12px}
.node{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:14px;border-radius:10px;border:1px solid var(--glass-border)}
.node h3{margin:0}
.node .summary{color:var(--muted)}
.toggle{margin-top:8px;padding:8px;border-radius:8px;border:1px solid var(--glass-border);background:transparent;color:var(--muted)}
.details.hidden{display:none}
.faq details{background:var(--card);padding:10px;border-radius:8px;margin:8px 0}
.cta{margin:28px 0;text-align:center}
.site-footer{border-top:1px solid var(--glass-border);padding:18px 0;margin-top:36px;color:var(--muted)}n
@media(max-width:800px){
  .hero-inner{flex-direction:column}
  .hero-pattern img{width:100%;max-width:420px}
  .nav{display:none}
}
/* subtle focus states */
select:focus, .toggle:focus, .btn:focus{outline:2px solid rgba(123,211,137,0.15)}
"}
{"path":"assets/js/main.js","content":"document.addEventListener('DOMContentLoaded',function(){
  // Mood-to-Method map
  var map = {
    "overwhelmed":{
      title:"Stabilize Sprint",
      desc:"A compact 2-week track to reduce overwhelm: simple routines, priority triage, and focused pacing.",
      cta:"Reserve a Stabilize Sprint"
    },
    "low_energy":{
      title:"Energy Reset Cycle",
      desc:"Three-week series emphasizing sleep patterns, gentle movement, and nutrition pivots to regain steady energy.",
      cta:"Join an Energy Reset"
    },
    "stuck":{
      title:"Pattern Shift Workshops",
      desc:"A focused cohort to identify repeating loops and practice new responses in small, practical steps.",
      cta:"Sign up for Pattern Shift"
    },
    "recovering":{
      title:"Recovery Navigation",
      desc:"A paced program to reconnect routines with recovery needs; safety-first, paced goals, community support.",
      cta:"Start Recovery Navigation"
    },
    "curious":{
      title:"Intro & Explore",
      desc:"A light, exploratory mini-series to try tools and decide which longer track fits best.",
      cta:"Explore Intro Series"
    }
  };

  var mood = document.getElementById('mood');
  var title = document.getElementById('method-title');
  var desc = document.getElementById('method-desc');
  var moodCta = document.getElementById('mood-cta');
  var headerCta = document.getElementById('primary-cta');

  function applyMood(key){
    var data = map[key] || map['curious'];
    title.textContent = data.title;
    desc.textContent = data.desc;
    moodCta.textContent = data.cta;
    // update header CTA phrasing to feel tailored
    if(headerCta) headerCta.textContent = data.cta;
    // append query for tracking
    var base = moodCta.getAttribute('href').split('?')[0];
    moodCta.setAttribute('href', base + '?mood=' + encodeURIComponent(key));
  }

  if(mood){
    applyMood(mood.value);
    mood.addEventListener('change',function(e){
      applyMood(e.target.value);
      // small animation
      var card = document.getElementById('method-recommendation');
      card.style.transform = 'translateY(-6px)';
      setTimeout(function(){card.style.transform='translateY(0)';},180);
      try{localStorage.setItem('preferred_mood', e.target.value);}catch(e){}
    });
  }

  // restore mood
  try{
    var saved = localStorage.getItem('preferred_mood');
    if(saved && mood){mood.value = saved; applyMood(saved);}    
  }catch(e){}

  // Timeline toggles
  var toggles = document.querySelectorAll('#timeline .toggle');
  toggles.forEach(function(btn){
    btn.addEventListener('click',function(){
      var parent = btn.parentElement;
      var details = parent.querySelector('.details');
      if(details.classList.contains('hidden')){
        details.classList.remove('hidden');
        btn.textContent = 'Hide details';
      } else {
        details.classList.add('hidden');
        btn.textContent = 'Details';
      }
    });
  });

  // small safety: disallow primary CTA click when no URL
  var final = document.getElementById('final-cta');
  if(final){
    final.addEventListener('click',function(e){
      var href = final.getAttribute('href') || '';
      if(!href || href.trim()==="{{PRIMARY_CTA_URL}}"){
        // allow default developer placeholder, but prevent if empty
      }
    });
  }
});
"}
